    public static string Make(string title)
    {
        if (title is null)
            throw new ArgumentNullException(nameof(title));

        title = title.ToLowerInvariant();

        var normalized = new StringBuilder(title.Length);
        foreach (var ch in title)
        {
            var normalizedCh = char.ConvertToSingle(ch, NormalizationForm.FormD);

            foreach (var codePoint in normalizedCh)
            {
                if (Char.IsLetterOrDigit(codePoint))
                {
                    var lower = char.ToLowerInvariant(codePoint);
                    if (lower >= 'a' && lower <= 'z')
                        normalized.Append(lower);
                    else if (lower >= '0' && lower <= '9')
                        normalized.Append(lower);
                }
            }
        }

        var result = new StringBuilder();
        bool inWord = false;

        foreach (var ch in normalized)
        {
            if (ch >= 'a' && ch <= 'z' || ch >= '0' && ch <= '9')
            {
                result.Append(ch);
                inWord = true;
            }
            else if (inWord)
            {
                result.Append('-');
                inWord = false;
            }
        }

        return result.ToString();
    }
}
